export const fieldById = (id: string): FieldDef | undefined => FIELDS.find((x) => x.id === id);
export const fieldsOfEntity = (entity: string): FieldDef[] => FIELDS.filter((x) => x.entity === entity);
export const intakeSteps = (): number[] => [...new Set(FIELDS.filter((x) => x.step > 0).map((x) => x.step))].sort((a, b) => a - b);
